describe("Cart.checkout() — async pipeline", () => {
  it("refreshes prices via priceFetcher before computing totals", async () => {
    const cart = new Cart();
    cart.add(productA, 1); // original 1000

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };
    const result = await cart.checkout({ priceFetcher });
    expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("a");
    expect(result.totals.subtotalCents).toBe(1500);
    expect(result.lines[0].product.unitPriceCents).toBe(1500);
  });

  it("validates inventory and throws InventoryError on denial", async () => {
    const cart = new Cart();
    cart.add(productA, 5);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        availableQuantity: 2,
        reason: "low stock",
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("a");
      expect(invErr.requested).toBe(5);
      expect(invErr.available).toBe(2);
      expect(invErr.message).toBe("low stock");
    }
  });

  it("throws InventoryError on partial-stock denial (available < requested)", async () => {
    const cart = new Cart();
    cart.add(productA, 10);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("a");
      expect(invErr.requested).toBe(10);
      expect(invErr.available).toBe(3);
    }
  });

  it("succeeds when inventory check passes", async () => {
    const cart = new Cart();
    cart.add(productA, 2);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2000);
  });

  it("uses asyncTaxProvider for tax computation", async () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const cart = new Cart({ discountPolicy: discount });
    cart.add(productA, 1); // subtotal 1000, discount 200, discounted = 800

    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const result = await cart.checkout({ asyncTaxProvider });
    // tax = floor(800 * 0.1) = 80
    expect(result.totals.taxCents).toBe(80);
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US");
  });

  it("combines priceFetcher + inventoryChecker + asyncTaxProvider", async () => {
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({ shippingCalculator: shipping, region: "FR" });
    cart.add(productA, 2);
    cart.add(productB, 1);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi
        .fn()
        .mockResolvedValueOnce(1200) // productA now 1200
        .mockResolvedValueOnce(2500), // productB now 2500
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.2),
    };

    const result = await cart.checkout({
      priceFetcher,
      inventoryChecker,
      asyncTaxProvider,
    });

    // subtotal = 1200*2 + 2500*1 = 4900
    expect(result.totals.subtotalCents).toBe(4900);
    // no discount by default → discountedSubtotal = 4900
    // tax = floor(4900 * 0.2) = 980
    expect(result.totals.taxCents).toBe(980);
    expect(result.totals.shippingCents).toBe(500);
    // total = 4900 + 980 + 500 = 6380
    expect(result.totals.totalCents).toBe(6380);
  });

  it("works with no collaborators at all", async () => {
    const cart = new Cart();
    cart.add(productA, 1);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(1000);
    expect(result.totals.totalCents).toBe(1000);
  });

  it("propagates asyncTaxProvider rejection", async () => {
    const cart = new Cart();
    cart.add(productA, 1);
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("rate service down")),
    };
    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
      "rate service down",
    );
  });

  it("propagates priceFetcher rejection", async () => {
    const cart = new Cart();
    cart.add(productA, 1);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price unavailable")),
    };
    await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
      "price unavailable",
    );
  });

  it("first inventory denial wins when multiple items fail", async () => {
    const cart = new Cart();
    cart.add(productA, 5);
    cart.add(productB, 3);

    const inventoryChecker: InventoryChecker = {
      check: vi
        .fn()
        .mockResolvedValueOnce({ available: false, reason: "A is gone" })
        .mockResolvedValueOnce({ available: false, reason: "B is gone" }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      // First denial wins
      expect((err as InventoryError).productId).toBe("a");
    }
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([0, 100, 5000, -50])(
    "returns 0 regardless of subtotal (%i)",
    (subtotal) => {
      expect(policy.computeDiscountCents(subtotal)).toBe(0);
    },
  );
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([-1, 101, NaN, Infinity, -Infinity])(
      "rejects out-of-range percent (%s)",
      (percent) => {
        expect(() => new PercentageDiscountPolicy(percent)).toThrow(RangeError);
      },
    );

    it.each([0, 50, 100])("accepts valid percent (%i)", (percent) => {
      expect(() => new PercentageDiscountPolicy(percent)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("computes 10% of 1000 as 100", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(1000)).toBe(100);
    });

    it("rounds down to nearest cent (floors)", () => {
      // 15% of 999 = 149.85 → 149
      const policy = new PercentageDiscountPolicy(15);
      expect(policy.computeDiscountCents(999)).toBe(149);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(-500)).toBe(0);
    });

    it("100% returns full subtotal", () => {
      const policy = new PercentageDiscountPolicy(100);
      expect(policy.computeDiscountCents(12345)).toBe(12345);
    });

    it("0% returns 0", () => {
      const policy = new PercentageDiscountPolicy(0);
      expect(policy.computeDiscountCents(12345)).toBe(0);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([-1, -100])("rejects negative amountCents (%i)", (amount) => {
      expect(() => new FixedAmountDiscountPolicy(amount)).toThrow(RangeError);
    });

    it("rejects non-integer amountCents", () => {
      expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
    });

    it("accepts zero", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns fixed amount when subtotal exceeds it", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(1000)).toBe(500);
    });

    it("caps at subtotal when fixed exceeds subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(300)).toBe(300);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("returns exact subtotal when equal to fixed amount", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(500)).toBe(500);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policies array", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from each child using original subtotal", () => {
      const p1 = new PercentageDiscountPolicy(10); // 10% of 1000 = 100
      const p2 = new FixedAmountDiscountPolicy(200); // 200
      const composite = new CompositeDiscountPolicy([p1, p2], "sum");
      // sum = 100 + 200 = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(-500)).toBe(0);
    });

    it("defaults to sum mode when not specified", () => {
      const p1 = new FixedAmountDiscountPolicy(100);
      const p2 = new FixedAmountDiscountPolicy(200);
      const composite = new CompositeDiscountPolicy([p1, p2]);
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("clamps negative child results to 0 before summing", () => {
      // NoDiscountPolicy returns 0, so total = 0 + fixed
      const composite = new CompositeDiscountPolicy(
        [new NoDiscountPolicy(), new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      expect(composite.computeDiscountCents(500)).toBe(100);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially to remaining subtotal", () => {
      // 10% of 1000 = 100, remaining 900; then fixed 200 off 900 = 200
      const p1 = new PercentageDiscountPolicy(10);
      const p2 = new FixedAmountDiscountPolicy(200);
      const composite = new CompositeDiscountPolicy([p1, p2], "chain");
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("respects ordering — different order yields different result", () => {
      // fixed 200 off 1000 first → remaining 800; then 10% of 800 = 80; total = 280
      const p1 = new FixedAmountDiscountPolicy(200);
      const p2 = new PercentageDiscountPolicy(10);
      const composite = new CompositeDiscountPolicy([p1, p2], "chain");
      expect(composite.computeDiscountCents(1000)).toBe(280);
    });

    it("stops accumulating once remaining hits zero", () => {
      // Two fixed 600 on subtotal 1000: first takes 600, remaining 400; second takes 400 (capped)
      const p1 = new FixedAmountDiscountPolicy(600);
      const p2 = new FixedAmountDiscountPolicy(600);
      const composite = new CompositeDiscountPolicy([p1, p2], "chain");
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });
});

