import { describe, it, expect, vi } from "vitest";
import {
  NoTaxCalculator,
  RegionalTaxCalculator,
  AsyncTaxCalculator,
  totalLineWeightGrams,
  type AsyncTaxRateProvider,
} from "../src/tax.ts";
import type { CartLine } from "../src/product.ts";

describe("NoTaxCalculator", () => {
  const calc = new NoTaxCalculator();

  it.each([
    [0, "US"],
    [1000, "FR"],
    [5000, "US-CA"],
  ])("returns 0 for taxable=%i region=%s", (taxable, region) => {
    expect(calc.computeTaxCents(taxable, region)).toBe(0);
  });
});

describe("RegionalTaxCalculator", () => {
  describe("constructor validation", () => {
    it("rejects defaultRate below 0", () => {
      expect(() => new RegionalTaxCalculator({}, -0.01)).toThrow(RangeError);
    });

    it("rejects defaultRate above 1", () => {
      expect(() => new RegionalTaxCalculator({}, 1.01)).toThrow(RangeError);
    });

    it("rejects NaN defaultRate", () => {
      expect(() => new RegionalTaxCalculator({}, NaN)).toThrow(RangeError);
    });

    it("rejects out-of-range rate in rates map", () => {
      expect(
        () => new RegionalTaxCalculator({ US: 1.5 }),
      ).toThrow(RangeError);
    });

    it("rejects negative rate in rates map", () => {
      expect(
        () => new RegionalTaxCalculator({ US: -0.1 }),
      ).toThrow(RangeError);
    });

    it("accepts valid boundary rates", () => {
      expect(
        () => new RegionalTaxCalculator({ US: 0, FR: 1 }, 0),
      ).not.toThrow();
    });
  });

  describe("computeTaxCents", () => {
    const rates = { "US-CA": 0.0875, FR: 0.2 };
    const calc = new RegionalTaxCalculator(rates, 0.05);

    it("uses region-specific rate", () => {
      // 8.75% of 10000 = 875
      expect(calc.computeTaxCents(10000, "US-CA")).toBe(875);
    });

    it("falls back to default rate for unknown region", () => {
      // 5% of 10000 = 500
      expect(calc.computeTaxCents(10000, "DE")).toBe(500);
    });

    it("floors to nearest cent", () => {
      // 20% of 999 = 199.8 → 199
      expect(calc.computeTaxCents(999, "FR")).toBe(199);
    });

    it("returns 0 for zero taxable", () => {
      expect(calc.computeTaxCents(0, "FR")).toBe(0);
    });

    it("returns 0 for negative taxable", () => {
      expect(calc.computeTaxCents(-500, "FR")).toBe(0);
    });

    it("uses 0 default rate when none specified", () => {
      const noDefault = new RegionalTaxCalculator({ US: 0.1 });
      expect(noDefault.computeTaxCents(1000, "UNKNOWN")).toBe(0);
    });
  });
});

describe("AsyncTaxCalculator", () => {
  it("computes tax using async provider rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const calc = new AsyncTaxCalculator(provider);
    const result = await calc.computeTaxCents(1000, "US");
    expect(result).toBe(100);
    expect(provider.getRate).toHaveBeenCalledWith("US");
  });

  it("floors the result", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.0875),
    };
    const calc = new AsyncTaxCalculator(provider);
    // 8.75% of 999 = 87.4125 → 87
    expect(await calc.computeTaxCents(999, "US-CA")).toBe(87);
  });

  it("returns 0 for zero taxable without calling provider", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(0, "US")).toBe(0);
    expect(provider.getRate).not.toHaveBeenCalled();
  });

  it("returns 0 for negative taxable", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(-100, "US")).toBe(0);
  });

  it("throws RangeError if provider returns rate > 1", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(1.5),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("throws RangeError if provider returns negative rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(-0.1),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("throws RangeError if provider returns NaN", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(NaN),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("propagates provider rejection", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("network down")),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(
      "network down",
    );
  });
});

describe("totalLineWeightGrams", () => {
  it("sums weight * quantity across lines", () => {
    const lines: CartLine[] = [
      { product: { id: "a", name: "A", unitPriceCents: 100, weightGrams: 200 }, quantity: 2 },
      { product: { id: "b", name: "B", unitPriceCents: 100, weightGrams: 500 }, quantity: 1 },
    ];
    expect(totalLineWeightGrams(lines)).toBe(900);
  });

  it("treats missing weightGrams as 0", () => {
    const lines: CartLine[] = [
      { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 3 },
    ];
    expect(totalLineWeightGrams(lines)).toBe(0);
  });

  it("returns 0 for empty lines", () => {
    expect(totalLineWeightGrams([])).toBe(0);
  });
});

