import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const makeLine = (
  id: string,
  weightGrams: number | undefined,
  quantity: number,
): CartLine => ({
  product: { id, name: id, unitPriceCents: 1000, weightGrams },
  quantity,
});

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for non-empty cart", () => {
    expect(calc.computeShippingCents([makeLine("a", 500, 2)], 5000)).toBe(0);
  });

  it("returns 0 for empty cart", () => {
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects negative flatCents", () => {
      expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
    });

    it("rejects non-integer flatCents", () => {
      expect(() => new FlatShippingCalculator(5.5)).toThrow(RangeError);
    });

    it("rejects negative freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
    });

    it("rejects non-integer freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 99.5)).toThrow(RangeError);
    });

    it("accepts zero flatCents and zero freeOverCents", () => {
      expect(() => new FlatShippingCalculator(0, 0)).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    it("returns flat rate for non-empty cart", () => {
      const calc = new FlatShippingCalculator(599);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 2000)).toBe(599);
    });

    it("returns 0 for empty cart", () => {
      const calc = new FlatShippingCalculator(599);
      expect(calc.computeShippingCents([], 0)).toBe(0);
    });

    it("returns 0 when subtotal meets free-over threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 5000)).toBe(0);
    });

    it("returns 0 when subtotal exceeds free-over threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 6000)).toBe(0);
    });

    it("returns flat rate when subtotal is below free-over threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 4999)).toBe(599);
    });

    it("returns flat rate when no freeOverCents is configured", () => {
      const calc = new FlatShippingCalculator(599);
      expect(
        calc.computeShippingCents([makeLine("a", 100, 1)], 100000),
      ).toBe(599);
    });
  });
});

describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects bracket with non-positive upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 0, costCents: 100 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 500, costCents: -1 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 500.5, costCents: 100 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 500, costCents: 10.5 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 500, costCents: 100 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 500, costCents: 100 }],
            10.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const brackets = [
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 500 },
      { upToGrams: 5000, costCents: 800 },
    ];

    it("returns 0 for empty cart", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([], 1000)).toBe(0);
    });

    it("returns 0 when total weight is 0 (no weightGrams)", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(
        calc.computeShippingCents([makeLine("a", undefined, 2)], 1000),
      ).toBe(0);
    });

    it("selects first bracket when weight is within it", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 200g * 2 = 400g → first bracket (≤500g) = 300
      expect(
        calc.computeShippingCents([makeLine("a", 200, 2)], 1000),
      ).toBe(300);
    });

    it("selects bracket at exact boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // exactly 500g → first bracket
      expect(
        calc.computeShippingCents([makeLine("a", 500, 1)], 1000),
      ).toBe(300);
    });

    it("selects next bracket when weight exceeds boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 501g → second bracket (≤1000g) = 500
      expect(
        calc.computeShippingCents([makeLine("a", 501, 1)], 1000),
      ).toBe(500);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      const calc = new WeightBasedShippingCalculator(brackets, 1200);
      // 6000g > 5000g → overflow = 1200
      expect(
        calc.computeShippingCents([makeLine("a", 6000, 1)], 1000),
      ).toBe(1200);
    });

    it("falls back to heaviest bracket cost when no overflow specified", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 6000g > 5000g → last bracket cost = 800
      expect(
        calc.computeShippingCents([makeLine("a", 6000, 1)], 1000),
      ).toBe(800);
    });

    it("sorts brackets internally regardless of input order", () => {
      const unordered = [
        { upToGrams: 5000, costCents: 800 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 500 },
      ];
      const calc = new WeightBasedShippingCalculator(unordered);
      // 400g → first bracket (500g) = 300
      expect(
        calc.computeShippingCents([makeLine("a", 400, 1)], 1000),
      ).toBe(300);
    });

    it("accumulates weight across multiple lines", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 300*1 + 400*1 = 700g → second bracket (≤1000g) = 500
      const lines = [makeLine("a", 300, 1), makeLine("b", 400, 1)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(500);
    });
  });
});

